import { Link } from "react-router-dom";

function Home() {

    const data = [
        {
            hh: "HTML",
            tt:"Learn how to create the structure of a website.",
            bb: "Learn HTML",
            url:"/html"
        },
        {
            hh: "CSS",
            tt:"Learn how to create the structure of a website.",
            bb:"Learn CSS",
            url:"/css"
        },
        {
            hh: "JS",
            tt:"Learn how to create the structure of a website.",
            bb: "Learn JS",
            url:"/js"
        },
        {
            hh: "React",
            tt:"Learn how to create the structure of a website.",
            bb:"Learn React",
            url:"/react"
        },
        {
            hh: "Node",
            tt:"Learn how to create the structure of a website.",
            bb: "Learn Node",
            url:"/node"
        },
    ]

    function welcomeMessage() {
        alert("Welcome to CodeLearn!");
    }

    function learnCourse(courseName) {
        alert("You selected " + courseName);
    }

    return (
        <div>

            <section className="hero">

                <h1>Learn Coding Easily</h1>

                <p>
                    Learn HTML, CSS, JavaScript, React and Node.js
                </p>

                <button
                    className="main-btn"
                    onClick={welcomeMessage}
                >
                    Start Learning
                </button>

            </section>


            <section className="courses">

                <h2>Our Courses</h2>

                <p className="course-text">
                    Start learning web development with simple courses.
                </p>


                <div className="cards">



                    data.map()
                    <div className="card">

                        <h3>HTML</h3>

                        <p>
                            Learn how to create the structure of a website.
                        </p>

                            <Link to="/html">
                                <button>

                            Learn HTML
                                </button>
                            </Link>


                    </div>



                </div>

            </section>

        </div>
    );
}

export default Home;
